def P1(x, y, z):
    return (x - y)**2 + (y - z)**2

# Test cases for P1(a, a+d, a+2d) = 2*d^2
differences = [2, 3, 4, 5]
results = {}

for d in differences:
    # We can set a=0 for simplicity, as P1 only depends on differences
    val = P1(0, d, 2*d)
    d_squared = d**2
    d_cubed = d**3

    is_divisible_by_d_squared = val % d_squared == 0
    is_divisible_by_d_cubed = val % d_cubed == 0

    results[d] = {
        "P1 value": val,
        "Div by d^2": is_divisible_by_d_squared,
        "Div by d^3": is_divisible_by_d_cubed
    }

print("--- Computational Check for P1(x, y, z) = (x-y)^2 + (y-z)^2 ---")
for d, data in results.items():
    print(f"d={d}: P1={data['P1 value']}. Divisible by d^2? {data['Div by d^2']}. Divisible by d^3? {data['Div by d^3']}.")
